@module sonority  src=sonority.lua  loc=595  mode=namespace  self=sonority

# Invariants & contracts
  @invariant  pure module: no state; ratios/cents are tuning.lua's, the placement carries them  @ 4
  @contract  strands, n, strength, notation, moves, offset → the cheapest Placement, or nil unplaced  @ 485
  @contract  the strand born first is the root, seated as written; each other moves from one placed  @ 486
  @contract  a strand may wait, taking its coords at a later onset from a neighbour sounding with it  @ 487
  @contract  cost is sonority.cost's own: the box over the walk, plus the pull each strand spends  @ 488
  @contract  raises where an onset reaches more entries than the budget allows  @ 489
  @contract  strands, n, strength, notation, moves → the cheapest placement over the sweep, or nil  @ 577
  @contract  eleven passes span the root strand's window  @ 578
  @contract  the winner is stated at the offset its own strands settle on, its cost read there  @ 579
  @contract  an offset refusing refuses nothing but itself, so nil means every offset refused  @ 580

# Shapes
  @shape  Coords = {[oddPrime]=exponent}; prime 2 is absent, so the score reads harmony not spacing  @ 5
  @shape  Strand = { notes={ {ppq,pitch,endppq,..},.. }, class=<step-class>, shortlist={ Candidate,.. } }; the walk reads the strikes, the releases and the class  @ 6
  @shape  Sonority = { ppq, strands={ strandIndex,.. } }; most recently struck first, the last n struck and whatever else still sounds  @ 7
  @shape  Candidate = { coords=Coords, strain=<distance from the written step, in half-windows> }  @ 8
  @shape  Tuning = { cents, coords=Coords, strain, key=<the coords' identity> }; what a placement seats a strand at  @ 9
  @shape  Placement = { cost, tunings={ [strandIndex]=Tuning,.. }, offset }; one tuning per strand, at a stated offset  @ 10

# Imports
  @const util = 'util'  @ 12
  @const tuning = 'tuning'  @ 13

# Module-level constants
  @const sonority = {}  @ 14
  @const budget = 200000  @ 188
  @const passes = 11  @ 191

# Private functions
  -- The box
  -- The strands
  -- The walk
  @fn strikesInOrder(strands)  @ 78-91
      -- Every strike, in onset order, lowest last — so a released chord leaves its
      -- bass to the sonority that follows (design/adaptive-tuning.md § The model).
  @fn sounding(strand, ppq)  @ 95-100
      -- Half-open, so a note released where the next is struck does not sound there,
      -- and a passage whose notes stop as the next begin reads as the last n struck.
  @fn promote(recent, strands, index)  @ 104-110
      -- The class holds one entry however many notes write it: a restrike moves its
      -- own entry to the front, and a second strand of the class takes the entry over.
  -- The objective
  -- The solve
  @fn schedule(strands, sonorities)  @ 158-184
      -- A strand is live from the onset it is chosen at to the last that reads it, both
      -- known before enumeration (§ Solving it), and listed in strand order for keying.
      @contract  strands, sonorities → per onset the strands born there, live there, and held from before  @ 157
  @fn assertAffordable(strands, plan)  @ 193-203
  @fn placementsAt(strands, born, strength)  @ 207-226
      -- Every combination of the shortlists of the strands born at an onset, with the
      -- pull each charges — the same against every state, so charged once here.
  @fn outranks(state, best, count, rankOf)  @ 231-239
      -- Cost, then the strands one by one, so an exact tie breaks deterministically rather than
      -- by table order (design/adaptive-tuning.md § What the solver takes).
      @contract  true iff `state` is the better of the two, the lower rank winning a tie  @ 230
  @fn byChoice(state, index)  @ 242-244
      -- Ranks a strand by the candidate index the solve chose for it.
  @fn keyOf(choice, list)  @ 246-250
  -- The placement
  @fn byTuningKey(entry, index)  @ 307-310
      -- An entry ranks on the coords each strand reached, and a strand it has yet to place
      -- ranks before any it has, so two entries compare on the strands they have in common.
  @fn anchorsOf(tunings, list)  @ 314-321
      -- The anchors themselves, in strand order, so that the candidates come back in one
      -- order however the placement was grown.
  @fn placementKey(tunings, list)  @ 325-331
      -- Two placements agreeing on the tuning of every strand listed are one, whichever order
      -- or history reached them; position names the strand, so an unplaced one keys as false.
  @fn attachable(sonorities, plan)  @ 336-352
      -- An onset striking a sonority's worth of classes evicts everything not still sounding,
      -- so the sonority before it stays attachable there, and only there (design/adaptive-ji.md § A placement is connected).
      @contract  sonorities, plan → per onset the attachable strands, and those the carry must tell apart  @ 335
  @fn spend(search)  @ 356-360
      -- Counted as the entries are reached rather than read off the walk: a strand's candidates
      -- depend on where the others went, so there is no product of shortlists to take in advance.
  @fn offering(partial, reached)  @ 364-376
      -- A partial made an answer of its own, remembering for each strand it leaves waiting the coords
      -- it could have taken here: the branch that took them carries them (design/adaptive-ji.md § A strand may wait).
  @fn growFrom(search, entry, onset, memory)  @ 380-450
      -- Grown outward from the root, taking any unplaced strand from any strand already placed:
      -- an order fixed in advance would lose the placements that reach a strand through a later one (design/adaptive-ji.md § What it costs to solve).
  @fn settle(placement, sonorities, unscored)  @ 455-467
      -- A sonority is scored when its last member places, which is its own onset unless a strand
      -- waited; the box reads coords, and the coords arrive late (design/adaptive-ji.md § A strand may wait).
      @contract  placement, the onsets it owes a box → its cost with those it can now take, and the rest  @ 454
  @fn reading(list, sonorities, pending)  @ 471-481
      -- What a waiting strand may still read: the members of every sonority its waiting leaves
      -- unscored, which join the list two entries are told apart on (§ What it costs to solve).
  @fn pullOf(strands, tunings, strength)  @ 539-546
      -- The pull a placement spends: strength × strain² per strand. The box reads coords alone, so
      -- re-reading the pull re-reads the whole cost (design/adaptive-ji.md § Where a placement sits).
  @fn settleOffset(placement, strands, notation, strength)  @ 552-573
      -- The placement stated where its own strands put it, offset clamped into the intersection
      -- of their windows (design/adaptive-ji.md § Where a placement sits).
      @contract  placement, strands → the same placement at the offset minimising its pull  @ 550
      @contract  the strains and the cost are re-read there, so the cost is the cost at the offset  @ 551

# Public API (sonority.*)
  @api sonority.score(coordSet)  @ 21-36
      -- The axes are gathered before any is measured, so an axis no member names doesn't reach
      -- back to 0; the spans are the octave-free lcm/gcd's coords, whose height tuning.height gives.
      @contract  coords[] → tuning.height of the coords of the set's octave-free lcm/gcd  @ 20
  @api sonority.strands(notes, classOf)  @ 44-72
      -- Notes of a class that overlap hold one tuning (§ The strand); the running
      -- release is half-open, so a note struck at a release starts another.
      @contract  notes, classOf → a Strand per class per run of overlapping notes, shortlists unfilled  @ 42
      @contract  grouped by ascending class, each in strike order, whatever order the notes arrive in  @ 43
  @api sonority.walk(strands, n)  @ 115-130
      -- The whole onset is absorbed before the sonority is taken, so a chord wider
      -- than n leaves its own lowest notes standing rather than its predecessor's.
      @contract  strands, n → a Sonority per onset: last n distinct classes struck, plus sounding  @ 114
  @api sonority.cost(strands, n, strength, choice)  @ 137-151
      -- The pull is counted once per strand rather than once per note, so an octave
      -- doubling changes no answer: the box already charges it nothing.
      @contract  strands, n, strength, choice → box over the walk + strength × strain² per strand  @ 136
  @api sonority.solveToPoints(strands, n, strength)  @ 256-301
      -- The state carries the whole choice vector rather than a backpointer: two
      -- generations are alive at a time and the budget bounds them.
      @invariant  reads no cents and knows no ratios — coords/strikes/releases/classes → indices  @ 254
      @contract  strands, n, strength → the index per strand minimising sonority.cost, exactly  @ 255
  @api sonority.placeAt(strands, n, strength, notation, moves, offset)  @ 490-535
      -- The candidate model of design/adaptive-ji.md: there is no shortlist to index, so
      -- the search carries the move set and reads the tunings off tuning.lua as it goes.
  @api sonority.solveToMoves(strands, n, strength, notation, moves)  @ 581-593
      -- One offset for the whole passage, run at each of eleven (design/adaptive-ji.md § What
      -- it costs to solve); outside the root's window costs nothing, tuning.origin refusing it.

